{
  "id": "council_tax_reduction",
  "benefit": "council_tax_reduction",
  "name": "Council Tax Reduction (pensioners)",
  "version": "2026-27",
  "jurisdiction": ["England", "Wales"],
  "sources": [
    {"url": "https://www.gov.uk/council-tax-reduction", "title": "Council Tax Reduction (GOV.UK)", "retrieved": "2026-10-27"},
    {"url": "https://www.legislation.gov.uk/uksi/2012/2885/contents", "title": "Council Tax Reduction Schemes (Prescribed Requirements) (England) Regulations 2012", "retrieved": "2026-10-27"}
  ],
  "clauses": [
    {"id": "CTR-1", "text": "You could be eligible if you're on a low income or claim benefits. Your bill could be reduced by up to 100%. Each council runs its own scheme; this model covers pensioners in England and Wales.", "source_url": "https://www.gov.uk/council-tax-reduction"},
    {"id": "CTR-2", "text": "The pensioner scheme applies to people who have reached State Pension age.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-3", "text": "The applicant must be liable to pay council tax on the home they live in.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-4", "text": "People who get the Guarantee Credit of Pension Credit get the maximum reduction (100% of the net council tax charge).", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-5", "text": "Otherwise, people with capital above £16,000 cannot get a reduction.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"},
    {"id": "CTR-6", "text": "Otherwise, the weekly reduction is the weekly net council tax charge (annual net charge divided by 52), less 20% of any weekly income above the applicable amount. The applicable amount is the Pension Credit guarantee amount (£238 single, £363.25 couple). Income counted from savings follows the Pension Credit rule (£1 a week for every £500, or part of £500, over £10,000). The household is eligible if the weekly reduction is greater than zero.", "source_url": "https://www.legislation.gov.uk/uksi/2012/2885/contents"}
  ],
  "derived": [
    {"name": "applicable_amount", "expr": {"if": {"field": "has_partner", "op": "==", "value": true, "clause": "CTR-6"}, "then": {"const": 363.25}, "else": {"const": 238}}, "clause": "CTR-6"},
    {"name": "income_from_savings", "expr": {"if": {"field": "savings", "op": ">", "value": {"const": 10000}, "clause": "CTR-6"}, "then": {"op": "ceil", "args": [{"op": "div", "args": [{"op": "sub", "args": [{"field": "savings"}, {"const": 10000}]}, {"const": 500}]}]}, "else": {"const": 0}}, "clause": "CTR-6"},
    {"name": "total_weekly_income", "expr": {"op": "add", "args": [{"field": "weekly_income_total"}, {"derived": "income_from_savings"}]}, "clause": "CTR-6"},
    {"name": "excess_income", "expr": {"op": "max", "args": [{"const": 0}, {"op": "sub", "args": [{"derived": "total_weekly_income"}, {"derived": "applicable_amount"}]}]}, "clause": "CTR-6"},
    {"name": "weekly_net_council_tax", "expr": {"op": "div", "args": [{"field": "council_tax_annual_net"}, {"const": 52}]}, "clause": "CTR-6"},
    {"name": "weekly_reduction", "expr": {"op": "sub", "args": [{"derived": "weekly_net_council_tax"}, {"op": "mul", "args": [{"const": 0.2}, {"derived": "excess_income"}]}]}, "clause": "CTR-6"}
  ],
  "eligibility": {
    "all": [
      {"field": "country", "op": "in", "value": ["England", "Wales"], "clause": "CTR-1"},
      {"field": "age_years", "op": ">=", "value": {"field": "state_pension_age"}, "clause": "CTR-2"},
      {"field": "council_tax_liable", "op": "==", "value": true, "clause": "CTR-3"},
      {
        "any": [
          {"field": "receives_pension_credit", "op": "==", "value": true, "clause": "CTR-4"},
          {
            "all": [
              {"field": "savings", "op": "<=", "value": {"const": 16000}, "clause": "CTR-5"},
              {"derived": "weekly_reduction", "op": ">", "value": {"const": 0}, "clause": "CTR-6"}
            ]
          }
        ]
      }
    ]
  },
  "amount": {
    "expr": {"if": {"field": "receives_pension_credit", "op": "==", "value": true, "clause": "CTR-4"}, "then": {"derived": "weekly_net_council_tax"}, "else": {"derived": "weekly_reduction"}},
    "unit": "weekly",
    "clause": "CTR-6",
    "min_if_unknown": 0
  },
  "questions": {
    "country": "In which country do you live? (England, Wales, Scotland, or Northern Ireland)",
    "date_of_birth": "What is your date of birth?",
    "council_tax_liable": "Are you liable to pay council tax for the home you live in?",
    "receives_pension_credit": "Do you currently receive Pension Credit (Guarantee Credit)?",
    "savings": "What is the total amount of savings and investments (capital) you and your partner have, in pounds?",
    "weekly_income_total": "What is your total weekly income from all sources (State Pension, private/occupational pensions, other income) for you and your partner, in pounds?",
    "has_partner": "Do you live with a partner?",
    "council_tax_annual_net": "What is your annual council tax charge after any single person discount, in pounds?"
  },
  "already_receiving_field": "receives_pension_credit",
  "notes": "Simplified national pensioner scheme model based on the Council Tax Reduction Schemes (Prescribed Requirements) (England) Regulations 2012 (SI 2012/2885). Each council in England and Wales operates its own scheme with possible variations. The applicable amounts (£238 single, £363.25 couple) and capital rules (£16,000 limit, £10,000 savings disregard, £1 per £500 taper) reflect the 2026-27 Pension Credit guarantee figures. The model assumes the claimant has reached State Pension age and is liable for council tax."
}
